{
  "schema_version": "rs-shopping-audit/3",
  "checks": {
    "naturalness": "pass",
    "extraction_fidelity": "fail",
    "fact_boundary": "pass",
    "clarification_policy": "pass"
  },
  "reasons": {
    "naturalness": "顾客原话自然、连贯，包含送礼对象、通勤用途、主要使用场景、佩戴舒适偏好、无线优先和对续航与降噪判断的求助。",
    "extraction_fidelity": "所有列出的 quote 和 intent.evidence 都是顾客原话中的逐字片段，没有发现拼接或伪引用；但 r2、r3 将使用场景标成 strict，强于原话表达。通勤、听音乐和接电话是预期用途，并未明确说成不可妥协的硬条件。其余主要需求和回答目标提取基本忠实。",
    "fact_boundary": "提取没有把目录标题中的宣传语当成已验证的续航、降噪或舒适度事实，也没有把赠送者的历史偏好转移给朋友。目录中的商品信息不足以证实具体产品表现，但本提取没有据此作出产品事实断言。",
    "clarification_policy": "顾客在询问选择建议，并明确表示不熟悉续航和降噪的判断方法；可以先解释判断方法并给出选择方向，不必先追问型号或补充偏好。没有当前动作必须依赖但被遗漏的必要信息。"
  },
  "evidence": [
    {
      "source": "customer",
      "quote": "想给朋友挑一副头戴式耳机当礼物，她平时通勤时想少受周围噪声影响，也会用来听音乐和接电话。"
    },
    {
      "source": "customer",
      "quote": "希望戴久了别太夹耳，预算不用卡得特别死；无线款优先，不过续航和降噪效果我不太会看，有什么合适的选择吗？"
    }
  ],
  "issues": [
    "requirements.r2 将“平时通勤时”标为 strict；这表达使用场景，不足以证明它是不可妥协的严格条件。",
    "requirements.r3 将“听音乐和接电话”标为 strict；原话说明预期用途，并未明确设为硬性门槛。"
  ]
}
